+func (f *G1) setBytes(b []byte) error {
+	err := f.g.SetBytes(b)
+	if err != nil {
+		return err
+	}
+
+	if f.g.IsIdentity() {
+		return ErrInvalidSig
+	}
+
+	return nil
+}
+
+func (f *G2) setBytes(b []byte) error {
+	err := f.g.SetBytes(b)
+	if err != nil {
+		return err
+	}
+
+	if f.g.IsIdentity() {
+		return ErrInvalidSig
+	}
+
+	return nil
+}

 func (f *G1) hash(msg []byte) { f.g.Hash(msg, []byte(dstG1)) }
 func (f *G2) hash(msg []byte) { f.g.Hash(msg, []byte(dstG2)) }
